<?php $gateway = App\Models\PaymentGateway::withoutGlobalScopes()->whereNull("company_id")->first(); $provider = app(App\Services\Payments\PaymentGatewayManager::class)->provider("razorpay"); $sub = $provider->createSubscription($gateway, ["name" => "5-Day Free Trial", "amount" => 500, "currency" => "INR", "period" => "monthly", "interval" => 1], ["total_count" => 120, "start_at" => now()->addDays(5)->timestamp, "notes" => []]); echo "Success: " . json_encode($sub);
